#include <algorithm>
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <utility>
#include <vector>
using namespace std;
using U=uint64_t;
void need(bool b,const char*s){if(!b)throw runtime_error(s);}
U hp(const vector<unsigned>& a){unsigned n=a.size(),N=1u<<n;vector<U>d(size_t(N)*n);for(unsigned i=0;i<n;i++)d[size_t(1u<<i)*n+i]=1;for(unsigned m=1;m<N;m++)for(unsigned u=0;u<n;u++){U z=d[size_t(m)*n+u];if(!z)continue;unsigned rem=a[u]&~m;while(rem){unsigned v=__builtin_ctz(rem);rem&=rem-1;d[size_t(m|(1u<<v))*n+v]+=z;}}U z=0;for(unsigned u=0;u<n;u++)z+=d[size_t(N-1)*n+u];return z;}
U query(const vector<unsigned>& a,unsigned x,unsigned c){unsigned n=a.size();vector<unsigned>b=a;b.push_back(1u<<(n+1));b.push_back(0);for(unsigned u=0;u<n;u++){if(x>>u&1)b[u]|=1u<<n;else b[n]|=1u<<u;if(c>>u&1)b[u]|=1u<<(n+1);else b[n+1]|=1u<<u;}return hp(b);}
vector<unsigned> build(bool reverse){vector<unsigned>a(9);for(unsigned u=0;u<9;u++)for(unsigned v=0;v<9;v++){if(u/3==v/3){if((v%3+3-u%3)%3==1)a[u]|=1u<<v;}else if((v/3+3-u/3)%3==(reverse?2:1))a[u]|=1u<<v;}return a;}
vector<unsigned> op(vector<unsigned>a){unsigned f=(1u<<a.size())-1;for(unsigned u=0;u<a.size();u++)a[u]^=f^(1u<<u);return a;}
int main(){auto a=build(false),b=build(true),o=op(a);vector<vector<unsigned>>rows={a,b,o};vector<unsigned>basis;for(unsigned m=0;m<512;m++)if(__builtin_popcount(m)<=2)basis.push_back(m);vector<vector<long long>>coeff;vector<vector<U>>values;unsigned checks=0;
for(auto&r:rows){vector<U>val;vector<long long>co;for(unsigned x:basis)for(unsigned c:basis)val.push_back(query(r,x,c));for(unsigned x:basis)for(unsigned c:basis){long long z=0;for(unsigned xx=x;;xx=(xx-1)&x){for(unsigned cc=c;;cc=(cc-1)&c){auto i=lower_bound(basis.begin(),basis.end(),xx)-basis.begin(),j=lower_bound(basis.begin(),basis.end(),cc)-basis.begin();long long sign=((__builtin_popcount(x^xx)+__builtin_popcount(c^cc))%2)?-1:1;z+=sign*static_cast<long long>(val[i*basis.size()+j]);if(cc==0)break;}if(xx==0)break;}co.push_back(z);}for(unsigned t=0;t<32;t++){unsigned x=(149*t+341)%512,c=(223*t+170)%512;long long z=0;size_t k=0;for(unsigned xx:basis)for(unsigned cc:basis){if((xx&x)==xx&&(cc&c)==cc)z+=co[k];k++;}need(z==static_cast<long long>(query(r,x,c)),"dense interpolation check");checks++;}values.push_back(val);coeff.push_back(co);}
need(hp(a)==3159&&hp(b)==3159,"Hamilton control");need(query(a,7,56)==70335&&query(b,7,56)==72387,"actual separator");size_t k=0;bool quartic=false;for(unsigned x:basis)for(unsigned c:basis){unsigned d=__builtin_popcount(x)+__builtin_popcount(c);if(d==4){need(coeff[0][k]==coeff[2][k],"whole converse quartic cancellation");if(coeff[0][k]!=coeff[1][k])quartic=true;}k++;}need(quartic,"partial reversal retains quartics");cout<<"{\"status\":\"PASS\",\"old_order\":9,\"basis_coordinates\":"<<basis.size()*basis.size()<<",\"dense_query_checks\":"<<checks<<",\"rows\":[";for(size_t i=0;i<rows.size();i++){if(i)cout<<',';cout<<'[';for(size_t j=0;j<9;j++){if(j)cout<<',';cout<<rows[i][j];}cout<<']';}cout<<"],\"coordinate_data\":[";k=0;for(unsigned x:basis)for(unsigned c:basis){if(k)cout<<',';cout<<'['<<x<<','<<c;for(auto&v:values)cout<<','<<v[k];for(auto&v:coeff)cout<<','<<v[k];cout<<']';k++;}cout<<"],\"coordinate_fields\":[\"a_mask\",\"c_mask\",\"F_T\",\"F_U\",\"F_Top\",\"coefficient_T\",\"coefficient_U\",\"coefficient_Top\"],\"uniform_query\":[7,56,70335,72387],\"H\":3159}\n";}
